    internal static bool Find(int font, int cp, bool text, out TexGlyphMetric metric)
    {
        int lo=0,hi=Entries.Length-1;while(lo<=hi){int mid=(lo+hi)>>>1;var e=Entries[mid];int cmp=font.CompareTo(e.Font);if(cmp==0)cmp=cp.CompareTo(e.CodePoint);if(cmp==0)cmp=text.CompareTo(e.TextMode);if(cmp==0){metric=e.Metric;return true;}if(cmp<0)hi=mid-1;else lo=mid+1;}metric=default;return false;
    }
